/* noise meter bars */
const MB = $('#mbars'), NB = 56, base = [];
for (let i = 0; i < NB; i++) { const v = i >= 20 && i < 38; base.push({ v, h: v ? 30 + Math.abs(Math.sin(i * 1.7)) * 65 : 18 + Math.abs(Math.sin(i * 2.3 + 1)) * 55 }); }
MB.innerHTML = base.map(b => `<i class="${b.v ? 'voice' : ''}" style="height:${b.h}%"></i>`).join('');
const setNoise = p => { const bars = MB.children; base.forEach((b, i) => { bars[i].style.height = (b.v ? b.h : Math.max(3, b.h * (1 - p * 0.92))) + '%'; }); $('#mstate').textContent = p > 0.6 ? 'Noise held back, your voice passes' : (p > 0.25 ? 'Hoola listens for a real voice' : 'Room noise'); };

/* ---------- night sky ---------- */
(function(){
  const c = $('#sky'), x = c.getContext('2d'); let W, H, stars;
  const L = [{c:'255,154,60',r:.55,x:.2,y:.25,p:0},{c:'192,85,245',r:.6,x:.82,y:.4,p:2},{c:'124,92,255',r:.7,x:.5,y:.9,p:4}];
  const size = () => { W = c.width = Math.round(innerWidth * .5); H = c.height = Math.round(innerHeight * .5); stars = Array.from({length: Math.round(W * H / 1500)}, () => ({x: Math.random() * W, y: Math.random() * H, r: Math.random() * .9 + .2, t: Math.random() * 6})); };
  const draw = t => {
    const sp = scrollY / Math.max(1, document.documentElement.scrollHeight - innerHeight);
    x.fillStyle = '#0B0A1A'; x.fillRect(0, 0, W, H); x.globalCompositeOperation = 'lighter';
    L.forEach(l => { const px = (l.x + Math.sin(t * .0001 + l.p) * .12) * W, py = (l.y + Math.cos(t * .00008 + l.p) * .1 - sp * .3) * H, R = l.r * Math.max(W, H), g = x.createRadialGradient(px, py, 0, px, py, R); g.addColorStop(0, `rgba(${l.c},.2)`); g.addColorStop(1, `rgba(${l.c},0)`); x.fillStyle = g; x.fillRect(0, 0, W, H); });
    x.globalCompositeOperation = 'source-over';
    const sa = .3 + sp * .7;
    stars.forEach(s => { x.fillStyle = `rgba(244,242,255,${sa * (.35 + .35 * Math.sin(t * .0012 + s.t))})`; x.fillRect(s.x, ((s.y - sp * 60) % H + H) % H, s.r, s.r); });
  };
  size(); addEventListener('resize', size);
  if (reduce) { draw(0); return; }
  (function loop(t){ draw(t); requestAnimationFrame(loop); })(0);
})();

/* ---------- hero conversation ---------- */
(function(){
  if (reduce) return;
  const lines = [['Santosh, kal ki meeting yaad hai?','Haan ji, 11 baje. Main 10:30 pe yaad dila dunga.'],['Ye bill kab tak bharna hai?','24 October tak, ₹1,840. Reminder 23 ko laga diya.'],['TV pe DD News laga do','Living room TV pe laga diya.'],['Dukaan ke WhatsApp dekh lo','6 chats ka jawab de diya. Ek refund pe aapki Haan chahiye.']];
  const you = $('#sayYou'), him = $('#sayHim'); let i = 0;
  const wait = ms => new Promise(r => setTimeout(r, ms));
  (async function cycle(){ for(;;){ await wait(3800); i = (i + 1) % lines.length; you.textContent = lines[i][0]; him.textContent = ''; await wait(600); for (const ch of lines[i][1]) { him.textContent += ch; await wait(26); } } })();
})();

/* ---------- motion ---------- */
const bar = $('#bar');
const setBar = dark => { bar.classList.toggle('dark', dark); bar.classList.toggle('light', !dark); };
if (!window.gsap || !window.ScrollTrigger || reduce) {
  setNoise(1); $$('.ns').forEach(n => n.classList.add('on')); $$('.lv')[2].classList.add('on');
  addEventListener('scroll', () => setBar(scrollY > $('#dawn').offsetHeight - 70), {passive:true});
} else {
  gsap.registerPlugin(ScrollTrigger);
  ScrollTrigger.create({ trigger: '#dawn', start: 'bottom 70px', onEnter: () => setBar(true), onLeaveBack: () => setBar(false) });

  // 1. sunrise on load, dusk on the way out
  gsap.from('#sunball', { y: 260, scale: .7, duration: 2.2, ease: 'expo.out' });
  gsap.from('#rays', { opacity: 0, scale: .6, duration: 2.4, ease: 'expo.out' });
  gsap.to('#rays', { rotate: 360, duration: 120, ease: 'none', repeat: -1 });
  gsap.from('#h1 .w', { y: 60, opacity: 0, rotateX: -40, duration: 1, ease: 'expo.out', stagger: .07, delay: .15 });
  gsap.from('.dawn .lead, .dawn .ctas, .dawn .note', { y: 24, opacity: 0, duration: .8, stagger: .08, ease: 'power3.out', delay: .6 });
  gsap.from('#santosh', { y: 80, opacity: 0, duration: 1.3, ease: 'expo.out', delay: .4 });
  gsap.from('.bub', { y: 20, scale: .9, opacity: 0, duration: .7, ease: 'back.out(1.7)', stagger: .25, delay: 1.1 });
  gsap.to('#santosh', { y: -10, duration: 2.8, ease: 'sine.inOut', yoyo: true, repeat: -1, delay: 1.6 });
  $$('.cnt').forEach(b => { const to = +b.dataset.to, s = b.dataset.s || '', o = { v: 0 }; gsap.to(o, { v: to, duration: 2, ease: 'power2.out', delay: .8, onUpdate: () => b.textContent = Math.round(o.v).toLocaleString('en-IN') + s }); });
  const out = { trigger: '#dawn', start: 'top top', end: 'bottom top', scrub: true };
  gsap.to('#sunball', { scrollTrigger: out, y: 300, scale: 1.25, ease: 'none' });
  gsap.to('#dusk', { scrollTrigger: { trigger: '#dawn', start: 'center top', end: 'bottom top', scrub: true }, opacity: 1, ease: 'none' });

  const mm = gsap.matchMedia();
  const big = '(min-width: 980px) and (min-height: 680px)', small = '(max-width: 979px), (max-height: 679px)';

  // 2. the day
  const day = $('#day'), chaps = $$('.chap'), n = chaps.length, sun = $('#arcSun');
  mm.add(big, () => {
    day.classList.add('pin');
    gsap.set(chaps.slice(1), { autoAlpha: 0 });
    day.style.setProperty('--tint', chaps[0].dataset.tint);
    const tl = gsap.timeline({ scrollTrigger: { trigger: '#chaps', start: 'top top', end: '+=' + (n * 85) + '%', pin: true, scrub: .8, anticipatePin: 1,
      onUpdate: s => {
        const p = s.progress, t = p, x = 20 + 1160 * t, y = 86 - 4 * 63 * t * (1 - t) * 1.0;
        sun.setAttribute('cx', x); sun.setAttribute('cy', (1 - t) * (1 - t) * 86 + 2 * (1 - t) * t * -40 + t * t * 86);
        const k = Math.min(n - 1, Math.round(p * (n - 1)));
        day.style.setProperty('--tint', chaps[k].dataset.tint); sun.setAttribute('fill', chaps[k].dataset.sun);
      } } });
    chaps.forEach((c, i) => {
      if (!i) return; const pr = chaps[i - 1];
      tl.to(pr.querySelector('.ct'), { y: -60, autoAlpha: 0, filter: 'blur(8px)', duration: .5, ease: 'power2.in' }, i)
        .to(pr.querySelector('.phone'), { y: -40, rotateY: -18, rotate: -3, autoAlpha: 0, duration: .5, ease: 'power2.in' }, i)
        .set(c, { autoAlpha: 1 }, i + .45)
        .from(c.querySelector('.ct'), { y: 70, autoAlpha: 0, filter: 'blur(8px)', duration: .6, ease: 'power3.out' }, i + .45)
        .from(c.querySelector('.time'), { scale: 1.4, transformOrigin: 'left bottom', duration: .6, ease: 'power3.out' }, i + .45)
        .from(c.querySelector('.phone'), { y: 90, rotateY: 18, rotate: 4, autoAlpha: 0, duration: .6, ease: 'power3.out' }, i + .45)
        .from(c.querySelectorAll('.it'), { y: 18, autoAlpha: 0, duration: .35, stagger: .07, ease: 'power2.out' }, i + .7)
        .to({}, { duration: .35 });
    });
    return () => { day.classList.remove('pin'); gsap.set(chaps, { clearProps: 'all' }); chaps.forEach(c => gsap.set(c.querySelectorAll('.ct,.phone,.it,.time'), { clearProps: 'all' })); };
  });
  mm.add(small, () => {
    chaps.forEach(c => {
      gsap.from(c.querySelectorAll('.it'), { y: 20, opacity: 0, duration: .6, stagger: .07, ease: 'power2.out', scrollTrigger: { trigger: c.querySelector('.phone'), start: 'top 80%' } });
      ScrollTrigger.create({ trigger: c, start: 'top 60%', end: 'bottom 40%', onToggle: s => { if (s.isActive) day.style.setProperty('--tint', c.dataset.tint); } });
    });
  });

  // 3. kinetic words
  const words = $('#words'), kws = $$('.kw'), wl = $('.wline');
  mm.add(big, () => {
    words.classList.add('pin');
    gsap.set(kws, { autoAlpha: 0, scale: .55, filter: 'blur(18px)' }); gsap.set(wl, { autoAlpha: 0, y: 40 });
    const t = gsap.timeline({ scrollTrigger: { trigger: '#words', start: 'top top', end: '+=160%', pin: true, scrub: .6 } });
    gsap.set(kws[0], { autoAlpha: 1, scale: 1, filter: 'blur(0px)' });
    kws.forEach((k, i) => { if (i) t.to(k, { autoAlpha: 1, scale: 1, filter: 'blur(0px)', duration: .5, ease: 'power3.out' }, i); t.to(k, { autoAlpha: 0, scale: 1.6, filter: 'blur(14px)', duration: .45, ease: 'power2.in' }, i + .6); });
    t.to(wl, { autoAlpha: 1, y: 0, duration: .5 }, kws.length + .1).to({}, { duration: .4 });
    return () => { words.classList.remove('pin'); gsap.set([...kws, wl], { clearProps: 'all' }); };
  });
  mm.add(small, () => { gsap.from(kws, { y: 50, opacity: 0, stagger: .1, duration: .7, ease: 'power3.out', scrollTrigger: { trigger: '#words', start: 'top 75%' } }); });

  // 4. noise shield
  setNoise(0);
  ScrollTrigger.create({ trigger: '#noise', start: 'top 70%', end: 'bottom 60%', scrub: .4, onUpdate: s => setNoise(s.progress) });
  gsap.ticker.add(t => { const bars = MB.children; base.forEach((b, i) => { if (b.v) bars[i].style.height = (b.h * (0.6 + 0.4 * Math.abs(Math.sin(t * 3 + i)))) + '%'; }); });

  // 5. faces fly in from everywhere and settle into the grid
  const faces = $$('.face');
  gsap.from(faces, { x: () => gsap.utils.random(-500, 500), y: () => gsap.utils.random(-300, 400), rotate: () => gsap.utils.random(-40, 40), scale: () => gsap.utils.random(.3, .8), opacity: 0,
    ease: 'power3.out', stagger: { each: .02, from: 'random' }, scrollTrigger: { trigger: '#fgrid', start: 'top 95%', end: 'center 55%', scrub: .8 } });

  // 6. trust dial
  const fill = $('#dialFill'), FL = fill.getTotalLength(), lvs = $$('.lv'), cap = $('#capTxt');
  fill.style.strokeDasharray = FL; fill.style.strokeDashoffset = FL;
  ScrollTrigger.create({ trigger: '#dial', start: 'top 80%', end: 'bottom 45%', scrub: .5, onUpdate: s => {
    const p = s.progress; fill.style.strokeDashoffset = FL * (1 - p);
    $('#needle').setAttribute('transform', `rotate(${-90 + 180 * p} 260 270)`);
    const k = p < .34 ? 0 : (p < .7 ? 1 : 2); lvs.forEach((l, i) => l.classList.toggle('on', i === k));
    cap.textContent = [0, 40, 150][k];
  } });
  gsap.from('.roles span', { y: 20, opacity: 0, stagger: .03, duration: .5, scrollTrigger: { trigger: '.roles', start: 'top 85%' } });

  // 7. network
  const np = $('#npath'), env = $('#env'), NL = np.getTotalLength(), steps = $$('.ns');
  np.style.strokeDasharray = NL; np.style.strokeDashoffset = NL;
  const place = p => { const pt = np.getPointAtLength(NL * p); env.setAttribute('transform', `translate(${pt.x} ${pt.y}) rotate(${Math.sin(p * Math.PI) * -14})`); };
  place(0);
  ScrollTrigger.create({ trigger: '#netgrid', start: 'top 70%', end: 'bottom 45%', scrub: .5, onUpdate: s => { np.style.strokeDashoffset = NL * (1 - s.progress); place(s.progress); steps.forEach((e, i) => e.classList.toggle('on', s.progress >= i / steps.length - .02)); } });

  // 8. inside: cards travel sideways
  const inside = $('#inside'), track = $('#track');
  mm.add(big, () => {
    inside.classList.add('side'); track.style.maxWidth = 'none';
    const dist = () => Math.max(0, track.scrollWidth - innerWidth + 60);
    gsap.to(track, { x: () => -dist(), ease: 'none', scrollTrigger: { trigger: '#inside', start: 'top top', end: () => '+=' + dist(), pin: true, scrub: .6, invalidateOnRefresh: true } });
    return () => { inside.classList.remove('side'); track.style.maxWidth = '1240px'; gsap.set(track, { clearProps: 'transform' }); };
  });
  mm.add(small, () => { $$('.dive').forEach(d => gsap.from(d, { y: 40, opacity: 0, duration: .6, ease: 'power3.out', scrollTrigger: { trigger: d, start: 'top 90%' } })); });

  // 10. promises: words light, the lock closes
  const allW = [];
  $$('[data-words]').forEach(v => {
    const walk = node => { if (node.nodeType === 3) { const f = document.createDocumentFragment(); node.textContent.split(/(\s+)/).forEach(t => { if (!t) return; if (/^\s+$/.test(t)) f.append(t); else { const s = document.createElement('span'); s.className = 'wd'; s.textContent = t; f.append(s); } }); node.replaceWith(f); } else [...node.childNodes].forEach(walk); };
    walk(v); const ws = [...v.querySelectorAll('.wd')]; allW.push(...ws);
    ScrollTrigger.create({ trigger: v, start: 'top 85%', end: 'bottom 60%', scrub: true, onUpdate: s => { const k = Math.round(s.progress * ws.length); ws.forEach((w, i) => w.classList.toggle('lit', i < k)); } });
  });
  gsap.fromTo('#shackle', { y: -22 }, { y: 0, ease: 'none', scrollTrigger: { trigger: '#promises', start: 'top 60%', end: 'bottom 70%', scrub: true } });

  // 11. timeline + faq
  gsap.fromTo('#tlfill', { height: '0%' }, { height: '100%', ease: 'none', scrollTrigger: { trigger: '#tl', start: 'top 75%', end: 'bottom 60%', scrub: true } });
  gsap.from('.mile', { y: 16, opacity: 0, stagger: .06, duration: .5, ease: 'power2.out', scrollTrigger: { trigger: '#tl', start: 'top 80%' } });
  gsap.from('details', { y: 20, opacity: 0, stagger: .06, duration: .5, scrollTrigger: { trigger: '#faq', start: 'top 85%' } });

  // 12. the moon rises
  gsap.from('#moon', { y: 120, scale: .6, opacity: 0, duration: 1.4, ease: 'expo.out', scrollTrigger: { trigger: '#get', start: 'top 80%' } });
}
